import UIKit

// Container app for the Lex keyboard extension.
//
// iOS requires an app to deliver a keyboard extension. This app does nothing
// beyond explaining how to enable the keyboard; it deliberately does not link
// liblex and does not share state with the extension (no App Group / no
// "Allow Full Access" in this version). All input logic lives in the keyboard
// extension (Keyboard.swift).

@main
final class AppDelegate: UIResponder, UIApplicationDelegate {
    var window: UIWindow?

    func application(
        _ application: UIApplication,
        didFinishLaunchingWithOptions launchOptions: [UIApplication.LaunchOptionsKey: Any]? = nil
    ) -> Bool {
        let window = UIWindow(frame: UIScreen.main.bounds)
        window.rootViewController = InstructionsViewController()
        window.makeKeyAndVisible()
        self.window = window
        return true
    }
}

private final class InstructionsViewController: UIViewController {
    override func viewDidLoad() {
        super.viewDidLoad()
        self.view.backgroundColor = .systemBackground

        let title_label = UILabel()
        title_label.text = "Lex"
        title_label.font = .systemFont(ofSize: 34, weight: .bold)
        title_label.textAlignment = .center

        let body_label = UILabel()
        body_label.numberOfLines = 0
        body_label.font = .systemFont(ofSize: 17)
        body_label.text = """
            Telex Vietnamese keyboard.

            To enable:
            1. Settings → General → Keyboard → Keyboards.
            2. Add New Keyboard… → Lex.

            To use:
            • In any text field, long-press the globe key and choose Lex.
            • Lex always types Vietnamese (Telex). To type something else,
              switch to another keyboard with the globe key.

            "Allow Full Access" is not required.
            """

        let stack = UIStackView(arrangedSubviews: [title_label, body_label])
        stack.axis = .vertical
        stack.spacing = 24
        stack.translatesAutoresizingMaskIntoConstraints = false
        self.view.addSubview(stack)

        let guide = self.view.safeAreaLayoutGuide
        NSLayoutConstraint.activate([
            stack.leadingAnchor.constraint(equalTo: guide.leadingAnchor, constant: 24),
            stack.trailingAnchor.constraint(equalTo: guide.trailingAnchor, constant: -24),
            stack.topAnchor.constraint(equalTo: guide.topAnchor, constant: 40),
        ])
    }
}

const std = @import("std");

const assert = std.debug.assert;
const expectEqual = std.testing.expectEqual;
const indexOfScalar = std.mem.indexOfScalar;
const isAlphabetic = std.ascii.isAlphabetic;
const maxInt = std.math.maxInt;
const toUpper = std.ascii.toUpper;

const Diacritic = enum(u8) {
    empty, // nguyên âm, không dấu.
    circumflex, // dấu nón: â, ô, ê.
    horn, // dấu móc: ư, ơ.
    breve, // dấu ă.
    stroke, // dấu gạch: đ.
};

const Tone = enum(u8) {
    level, // thanh ngang, không dấu.
    rising, // sắc.
    falling, // huyền.
    dipping_rising, // hỏi.
    rising_glottalized, // ngã.
    falling_glottalized, // nặng.
};

const Span = struct {
    // Alphabet ASCII character, could be lowercase or uppercase.
    base: u8,
    // By default, it's plain alphabet character.
    diacritic: Diacritic = .empty,
    // By default, no tone is placed.
    tone: Tone = .level,

    // Create a Span with plain alphabet character, no diacritic, no tone.
    fn init(base: u8) Span {
        return Span.init_diacritic_tone(base, .empty, .level);
    }

    // Create a Span with diacritic, no tone.
    fn init_diacritic(base: u8, diacritic: Diacritic) Span {
        return Span.init_diacritic_tone(base, diacritic, .level);
    }

    fn init_diacritic_tone(base: u8, diacritic: Diacritic, tone: Tone) Span {
        // Only allow a-zA-Z.
        assert(isAlphabetic(base));

        // Only allow a valid Vietnamese alphabet combinations.
        switch (diacritic) {
            // All alphabet is allowed without diacritic.
            .empty => {},
            // Only a, o, e are valid with circumflex.
            .circumflex => switch (base) {
                'A', 'E', 'O', 'a', 'e', 'o' => {},
                else => unreachable,
            },
            // Only u, o are valid with horn.
            .horn => switch (base) {
                'O', 'U', 'o', 'u' => {},
                else => unreachable,
            },
            // Only a is valid with breve.
            .breve => switch (base) {
                'A', 'a' => {},
                else => unreachable,
            },
            // Only d is valid with stroke.
            .stroke => switch (base) {
                'D', 'd' => {},
                else => unreachable,
            },
        }

        // Only allow tone on valid Vietnamese vowels based on Vietnamese rules.
        switch (tone) {
            // All alphabet is allowed with level.
            .level => {},
            // All vowels is allowed with remaining tones.
            .rising, .falling, .dipping_rising, .rising_glottalized, .falling_glottalized => switch (base) {
                'A', 'E', 'I', 'O', 'U', 'Y', 'a', 'e', 'i', 'o', 'u', 'y' => {},
                else => unreachable,
            },
        }

        return .{ .base = base, .diacritic = diacritic, .tone = tone };
    }

    // Compare only base character, ignore case and other aspects.
    fn equals_ignore_case_diacritic_tone(self: *const Span, base: u8) bool {
        // Base must be alphabet letters.
        assert(isAlphabetic(base));

        return toUpper(self.base) == toUpper(base);
    }

    // Compare the span with a base character (ignore case) and diacritic, tone is ignored.
    fn equals_ignore_case_tone(self: *const Span, base: u8, diacritic: Diacritic) bool {
        // Base must be alphabet letters.
        assert(isAlphabetic(base));

        return toUpper(self.base) == toUpper(base) and self.diacritic == diacritic;
    }

    // Compare the Span base (ignore case), diacritic, tone.
    fn equals_ignore_case(self: *const Span, base: u8, diacritic: Diacritic, tone: Tone) bool {
        // Base must be alphabet letters.
        assert(isAlphabetic(base));

        return toUpper(self.base) == toUpper(base) and self.diacritic == diacritic and self.tone == tone;
    }

    // Check if the Span.base is vowel or not.
    fn is_vowel(self: *const Span) bool {
        return switch (toUpper(self.base)) {
            'A', 'E', 'I', 'O', 'U', 'Y' => true,
            else => false,
        };
    }

    // Check if the Span.base is consonant or not.
    fn is_consonant(self: *const Span) bool {
        return !self.is_vowel();
    }

    fn to_utf16(self: *const Span) u16 {
        assert(isAlphabetic(self.base));

        // fast path, plain alphabet.
        if (self.diacritic == .empty and self.tone == .level) {
            return self.base;
        }

        switch (self.base) {
            'a' => {
                switch (self.diacritic) {
                    .empty => {
                        switch (self.tone) {
                            .level => unreachable,
                            .rising => return 0x00E1, // á.
                            .falling => return 0x00E0, // à.
                            .dipping_rising => return 0x1EA3, // ả.
                            .rising_glottalized => return 0x00E3, // ã.
                            .falling_glottalized => return 0x1EA1, // ạ.
                        }
                    },
                    .breve => {
                        switch (self.tone) {
                            .level => return 0x0103, // ă.
                            .rising => return 0x1EAF, // ắ.
                            .falling => return 0x1EB1, // ằ.
                            .dipping_rising => return 0x1EB3, // ẳ.
                            .rising_glottalized => return 0x1EB5, // ẵ.
                            .falling_glottalized => return 0x1EB7, // ặ.
                        }
                    },
                    .circumflex => {
                        switch (self.tone) {
                            .level => return 0x00E2, // â.
                            .rising => return 0x1EA5, // ấ.
                            .falling => return 0x1EA7, // ầ.
                            .dipping_rising => return 0x1EA9, // ẩ.
                            .rising_glottalized => return 0x1EAB, // ẫ.
                            .falling_glottalized => return 0x1EAD, // ậ.
                        }
                    },
                    .horn, .stroke => unreachable,
                }
            },
            'A' => {
                switch (self.diacritic) {
                    .empty => {
                        switch (self.tone) {
                            .level => unreachable,
                            .rising => return 0x00C1, // Á.
                            .falling => return 0x00C0, // À.
                            .dipping_rising => return 0x1EA2, // Ả.
                            .rising_glottalized => return 0x00C3, // Ã.
                            .falling_glottalized => return 0x1EA0, // Ạ.
                        }
                    },
                    .breve => {
                        switch (self.tone) {
                            .level => return 0x0102, // Ă.
                            .rising => return 0x1EAE, // Ắ.
                            .falling => return 0x1EB0, // Ằ.
                            .dipping_rising => return 0x1EB2, // Ẳ.
                            .rising_glottalized => return 0x1EB4, // Ẵ.
                            .falling_glottalized => return 0x1EB6, // Ặ.
                        }
                    },
                    .circumflex => {
                        switch (self.tone) {
                            .level => return 0x00C2, // Â.
                            .rising => return 0x1EA4, // Ấ.
                            .falling => return 0x1EA6, // Ầ.
                            .dipping_rising => return 0x1EA8, // Ẩ.
                            .rising_glottalized => return 0x1EAA, // Ẫ.
                            .falling_glottalized => return 0x1EAC, // Ậ.
                        }
                    },
                    .horn, .stroke => unreachable,
                }
            },
            'd' => {
                assert(self.diacritic == .stroke);
                assert(self.tone == .level);
                return 0x0111; // đ.
            },
            'D' => {
                assert(self.diacritic == .stroke);
                assert(self.tone == .level);
                return 0x0110; // Đ.
            },
            'e' => {
                switch (self.diacritic) {
                    .empty => {
                        switch (self.tone) {
                            .level => unreachable,
                            .rising => return 0x00E9, // é.
                            .falling => return 0x00E8, // è.
                            .dipping_rising => return 0x1EBB, // ẻ.
                            .rising_glottalized => return 0x1EBD, // ẽ.
                            .falling_glottalized => return 0x1EB9, // ẹ.
                        }
                    },
                    .circumflex => {
                        switch (self.tone) {
                            .level => return 0x00EA, // ê.
                            .rising => return 0x1EBF, // ế.
                            .falling => return 0x1EC1, // ề.
                            .dipping_rising => return 0x1EC3, // ể.
                            .rising_glottalized => return 0x1EC5, // ễ.
                            .falling_glottalized => return 0x1EC7, // ệ.
                        }
                    },
                    .horn, .breve, .stroke => unreachable,
                }
            },
            'E' => {
                switch (self.diacritic) {
                    .empty => {
                        switch (self.tone) {
                            .level => unreachable,
                            .rising => return 0x00C9, // É.
                            .falling => return 0x00C8, // È.
                            .dipping_rising => return 0x1EBA, // Ẻ.
                            .rising_glottalized => return 0x1EBC, // Ẽ.
                            .falling_glottalized => return 0x1EB8, // Ẹ.
                        }
                    },
                    .circumflex => {
                        switch (self.tone) {
                            .level => return 0x00CA, // Ê.
                            .rising => return 0x1EBE, // Ế.
                            .falling => return 0x1EC0, // Ề.
                            .dipping_rising => return 0x1EC2, // Ể.
                            .rising_glottalized => return 0x1EC4, // Ễ.
                            .falling_glottalized => return 0x1EC6, // Ệ.
                        }

#ifndef LEX_H
#define LEX_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

#ifdef __cplusplus
extern "C" {
#endif

// Required allocation size of the engine state, in bytes.
extern const size_t lex_state_size;

// Required allocation alignment of the engine state, in bytes.
extern const size_t lex_state_alignment;

// Initialize a state buffer. The buffer must be at least `lex_state_size`
// bytes and aligned to `lex_state_alignment`.
void lex_init(void *state);

// Feed one ASCII alphabetic character (a-zA-Z) into the engine.
void lex_add(void *state, uint8_t c);

// Apply a single backspace to the engine state.
void lex_backspace(void *state);

uint8_t lex_calculate_synthetic_backspaces(void *state);

bool lex_buffer_effective_full(void *state);

// Indicate the buffer_length is at the maximum limit.
bool lex_buffer_full(void *state);

// Indicate the buffer_length is zero.
bool lex_buffer_empty(void *state);

extern const size_t lex_replacement_buffer_length;

// `replacement_buffer` capacity must be exactly `lex_replacement_buffer_length`.
void lex_compose_utf16_string_replacement(
    void *state,
    uint16_t *replacement_buffer,
    uint8_t *replacement_count);

#ifdef __cplusplus
}
#endif

#endif // LEX_H

        // Fail safe: never delete host text we cannot account for. If the engine
        // produced no replacement, or asks to drop more than we own, reset and
        // insert the key literally rather than corrupting the document.
        guard !composed.isEmpty, self.remove_owned_suffix_chars(backspaces) else {
            self.engine.reset()
            self.owned_suffix = ""
            proxy.insertText(text)
            return
        }

        for _ in 0..<backspaces {
            proxy.deleteBackward()
        }
        proxy.insertText(composed)
        self.owned_suffix += composed
    }

    // Drop `count` characters from the owned-suffix model, mirroring the
    // synthetic backspaces sent to the document. Returns false (without
    // mutating) when we do not own that many characters — a desync signal.
    private func remove_owned_suffix_chars(_ count: Int) -> Bool {
        guard count >= 0, count <= self.owned_suffix.count else {
            return false
        }
        for _ in 0..<count {
            self.owned_suffix.removeLast()
        }
        return true
    }

    private func handle_backspace() {
        self.engine.backspace()
        self.textDocumentProxy.deleteBackward()
        if !self.owned_suffix.isEmpty {
            self.owned_suffix.removeLast()
        }
    }

    private func handle_space() {
        self.engine.reset()
        self.owned_suffix = ""
        self.textDocumentProxy.insertText(" ")
    }

    private func handle_return() {
        self.engine.reset()
        self.owned_suffix = ""
        self.textDocumentProxy.insertText("\n")
    }

    // MARK: Traits

    private func refresh_traits(force: Bool) {
        let dark = self.is_dark_appearance()
        let return_title = self.return_key_title()
        let shows_globe = self.needsInputModeSwitchKey

        if !force,
            dark == self.applied_dark,
            return_title == self.applied_return_title,
            shows_globe == self.applied_shows_globe
        {
            return
        }

        self.applied_dark = dark
        self.applied_return_title = return_title
        self.applied_shows_globe = shows_globe

        self.keyboard_view.shows_globe = shows_globe
        self.keyboard_view.return_title = return_title
        self.keyboard_view.apply_appearance(dark: dark)
    }

    private func is_dark_appearance() -> Bool {
        switch self.textDocumentProxy.keyboardAppearance {
        case .dark:
            return true
        case .light:
            return false
        default:
            return self.traitCollection.userInterfaceStyle == .dark
        }
    }

    private func return_key_title() -> String {
        switch self.textDocumentProxy.returnKeyType {
        case .go:
            return "Go"
        case .google, .yahoo, .search:
            return "Search"
        case .send:
            return "Send"
        case .next:
            return "Next"
        case .done:
            return "Done"
        case .continue:
            return "Continue"
        case .join:
            return "Join"
        case .route:
            return "Route"
        default:
            return "return"
        }
    }
}

extension KeyboardViewController: KeyboardViewDelegate {
    fileprivate func keyboard_view(_ view: KeyboardView, didEmit action: KeyAction) {
        switch action {
        case .character(let text):
            self.handle_character(text)
        case .backspace:
            self.handle_backspace()
        case .space:
            self.handle_space()
        case .enter:
            self.handle_return()
        case .nextKeyboard:
            self.advanceToNextInputMode()
        case .shift, .plane:
            // UI-only state, handled inside KeyboardView.
            break
        }
    }
}

// MARK: - Keyboard UI model

private enum KeyAction {
    case character(String)
    case backspace
    case shift
    case space
    case enter
    case nextKeyboard
    case plane(KeyPlane)
}

private enum KeyPlane {
    case letters, numbers, symbols
}

private enum KeyWidth {
    case unit
    case fill
    case ratio(CGFloat)
}

private enum KeyStyle {
    case letter
